import numpy as np
def f(inp):
    inp=np.array(inp); out=inp.copy()
    bg=inp[0][0]
    marks=[(i,j) for i in range(inp.shape[0]) for j in range(inp.shape[1]) if inp[i][j]!=bg]
    seen=set()
    # horizontal: consecutive mark pairs in each row
    for r in range(inp.shape[0]):
        cs=[j for j in range(inp.shape[1]) if inp[r][j]!=bg]
        for k in range(len(cs)-1):
            lo,hi=cs[k],cs[k+1]
            for j in range(lo+1,hi):
                if inp[r][j]==bg: out[r][j]=3
    for c in range(inp.shape[1]):
        rs=[i for i in range(inp.shape[0]) if inp[i][c]!=bg]
        for k in range(len(rs)-1):
            lo,hi=rs[k],rs[k+1]
            for i in range(lo+1,hi):
                if inp[i][c]==bg: out[i][c]=3
    return out.tolist()
